import{_ as l,a0 as o,w as p,s as r,I as a,x as e,a1 as t,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Fedora、CentOS、RHEL 中啓用 RPM Fusion 倉庫 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora、CentOS、RHEL 中啓用 RPM Fusion 倉庫 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora、CentOS、RHEL 中啓用 RPM Fusion 倉庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora、CentOS、RHEL 中啓用 RPM Fusion 倉庫 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221002 How to Enable RPM Fusion Repo in Fedora, CentOS, RHEL","title":"如何在 Fedora、CentOS、RHEL 中啓用 RPM Fusion 倉庫","tag":"202210","desc":""},"relativePath":"202210/20221002 How to Enable RPM Fusion Repo in Fedora, CentOS, RHEL.md","filePath":"[post].md"}'),h={name:"202210/20221002 How to Enable RPM Fusion Repo in Fedora, CentOS, RHEL.md"};function g(u,s,k,c,f,b){const i=o("Link");return p(),r("div",null,[s[17]||(s[17]=a("h1",{id:"如何在-fedora、centos、rhel-中啓用-rpm-fusion-倉庫",tabindex:"-1"},[e("如何在 Fedora、CentOS、RHEL 中啓用 RPM Fusion 倉庫 "),a("a",{class:"header-anchor",href:"#如何在-fedora、centos、rhel-中啓用-rpm-fusion-倉庫","aria-label":"Permalink to “如何在 Fedora、CentOS、RHEL 中啓用 RPM Fusion 倉庫”"},"​")],-1)),s[18]||(s[18]=a("blockquote",null,[a("p",null,"本指南解釋了在 Fedora Linux 發行版中啓用第三方軟件倉庫 RPM Fusion 的步驟。")],-1)),a("p",null,[t(i,{href:"https://rpmfusion.org/"},{default:n(()=>[...s[0]||(s[0]=[e("RPM Fusion",-1)])]),_:1}),s[1]||(s[1]=e(" 軟件倉庫是一個社區維護的軟件倉庫，它為 Fedora Linux 提供額外的軟件包，這些軟件包不是由 Fedora 官方團隊分發，例如 DVD 播放、媒體播放、來自 GNOME 和 KDE 的軟件等。這是因為許可證、其他法律原因和特定國家/地區的軟件規範而導致的。",-1))]),s[19]||(s[19]=d('<p>RPM Fusion 為 Red Hat Enterprise Linux（RHEL）以及 Fedora 提供了 .rpm 包。</p><p>本指南介紹了在 Fedora Linux 中啓用 RPM Fusion 倉庫所需的步驟。本指南適用於所有 Fedora 發行版本。</p><p>這在所有當前支持的 Fedora 版本（35、36 和 37）中進行了測試。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202210/16/111338jjr0eh5cjgq017n5.jpg" alt=""></p><h3 id="如何在-fedora-linux、rhel、centos-中啓用-rpm-fusion-倉庫" tabindex="-1">如何在 Fedora Linux、RHEL、CentOS 中啓用 RPM Fusion 倉庫 <a class="header-anchor" href="#如何在-fedora-linux、rhel、centos-中啓用-rpm-fusion-倉庫" aria-label="Permalink to “如何在 Fedora Linux、RHEL、CentOS 中啓用 RPM Fusion 倉庫”">​</a></h3><p>RPM Fusion 有兩種版本的倉庫：自由和非自由。</p><p>顧名思義，自由版包含軟件包的自由版本，非自由版包含封閉源代碼的編譯軟件包和“非商業”開源軟件。</p><p>在繼續之前，首先檢查你是否安裝了 RPM fusion。打開終端並運行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf repolist | grep rpmfusion</span></span></code></pre></div><p>如果安裝了 RPM，你應該會看到如下所示的消息。就不用下面的步驟。如果未安裝，你可以繼續執行以下步驟。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/07/RPM-Fusion-Already-Installed-.png" alt="RPM Fusion 已安裝"></p><p>打開終端並根據你的操作系統版本運行以下命令。請注意，這些命令包含自由和非自由版本。如果你願意，你可以在運行時省略下面的任何一個。</p><h4 id="fedora" tabindex="-1">Fedora <a class="header-anchor" href="#fedora" aria-label="Permalink to “Fedora”">​</a></h4><p>自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install https://download1.rpmfusion.org/free/fedora/rpmfusion-free-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><p>非自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install https://download1.rpmfusion.org/nonfree/fedora/rpmfusion-nonfree-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><h4 id="在-silverblue-上使用-rpm-ostree" tabindex="-1">在 Silverblue 上使用 rpm-ostree <a class="header-anchor" href="#在-silverblue-上使用-rpm-ostree" aria-label="Permalink to “在 Silverblue 上使用 rpm-ostree”">​</a></h4><p>自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rpm-ostree install https://download1.rpmfusion.org/free/fedora/rpmfusion-free-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><p>非自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rpm-ostree install https://download1.rpmfusion.org/nonfree/fedora/rpmfusion-nonfree-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><h4 id="rhel-8" tabindex="-1">RHEL 8 <a class="header-anchor" href="#rhel-8" aria-label="Permalink to “RHEL 8”">​</a></h4><p>先安裝 EPEL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheck https://dl.fedoraproject.org/pub/epel/epel-release-latest-8.noarch.rpm</span></span></code></pre></div><p>自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheck https://download1.rpmfusion.org/free/el/rpmfusion-free-release-8.noarch.rpm</span></span></code></pre></div><p>非自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheckhttps://download1.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-8.noarch.rpm</span></span></code></pre></div><p>開發相關軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo subscription-manager repos --enable &quot;codeready-builder-for-rhel-8-$(uname -m)-rpms&quot;</span></span></code></pre></div><h4 id="centos-8" tabindex="-1">CentOS 8 <a class="header-anchor" href="#centos-8" aria-label="Permalink to “CentOS 8”">​</a></h4><p>先安裝 EPEL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheck https://dl.fedoraproject.org/pub/epel/epel-release-latest-8.noarch.rpm</span></span></code></pre></div><p>自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheck https://download1.rpmfusion.org/free/el/rpmfusion-free-release-8.noarch.rpm</span></span></code></pre></div><p>非自由版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install --nogpgcheckhttps://download1.rpmfusion.org/nonfree/el/rpmfusion-nonfree-release-8.noarch.rpm</span></span></code></pre></div><p>啓用 PowerTools：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf config-manager --enable PowerTools</span></span></code></pre></div><h3 id="附加説明" tabindex="-1">附加説明 <a class="header-anchor" href="#附加説明" aria-label="Permalink to “附加説明”">​</a></h3><p>RPM Fusion 還可以幫助用户安裝來自 GNOME 軟件或 KDE Discover 的軟件包。要在 Fedora 中啓用它，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf groupupdate core</span></span></code></pre></div><p>你還可以通過以下命令啓用 RPM Fusion 來使用 gstreamer 和其他多媒體播放包來播放媒體文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf groupupdate multimedia --setop=&quot;install_weak_deps=False&quot; --exclude=PackageKit-gstreamer-plugin</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf groupupdate sound-and-video</span></span></code></pre></div><p>啓用 RPM Fusion 以使用 libdvdcss 播放 DVD。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install rpmfusion-free-release-taintedsudo dnf install libdvdcss</span></span></code></pre></div><p>通過以下命令啓用 RPM Fusion 以啓用非 FLOSS 硬件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install rpmfusion-nonfree-release-taintedsudo dnf install *-firmware</span></span></code></pre></div><p>運行命令後，如果你使用的是 Fedora 或 CentOS/RHEL，請在重啓前運行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf check-updatesudo dnf update</span></span></code></pre></div><h3 id="如何使用-dnf-刪除倉庫" tabindex="-1">如何使用 dnf 刪除倉庫 <a class="header-anchor" href="#如何使用-dnf-刪除倉庫" aria-label="Permalink to “如何使用 dnf 刪除倉庫”">​</a></h3><p>如果要刪除倉庫，請按照以下步驟操作。</p><p>首先，使用以下命令查看添加到 Fedora 系統的倉庫列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf repolist</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/07/dnf-repolist.jpg" alt="dnf 倉庫列表"></p><p>如你所見，添加了 rpmfusion 自由和非自由倉庫。要通過 dnf 刪除它，你需要使用以下命令準確知道倉庫文件名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rpm -qa &#39;rpmfusion*&#39;</span></span></code></pre></div><p>這將列出倉庫的確切名稱。在示例中，它們是 “rpmfusion-free-release”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2020/07/remove-rpmfusion-from-fedora.jpg" alt="從 Fedora 中移除 rpmfusion"></p><p>現在你可以簡單地運行以下命令來刪除它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf remove rpmfusion-free-release</span></span></code></pre></div><p>你可以重複上面的例子從 Fedora 中刪除 rpmfusion，也可以使用它從系統中刪除任何其他倉庫。</p><hr>',65)),a("p",null,[s[3]||(s[3]=e("via: ",-1)),t(i,{href:"https://www.debugpoint.com/enable-rpm-fusion-fedora-rhel-centos/"},{default:n(()=>[...s[2]||(s[2]=[e("https://www.debugpoint.com/enable-rpm-fusion-fedora-rhel-centos/",-1)])]),_:1})]),a("p",null,[s[8]||(s[8]=e("作者：",-1)),t(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...s[4]||(s[4]=[e("Arindam",-1)])]),_:1}),s[9]||(s[9]=e(" 選題：",-1)),t(i,{href:"https://github.com/lkxed"},{default:n(()=>[...s[5]||(s[5]=[e("lkxed",-1)])]),_:1}),s[10]||(s[10]=e(" 譯者：",-1)),t(i,{href:"https://github.com/geekpi"},{default:n(()=>[...s[6]||(s[6]=[e("geekpi",-1)])]),_:1}),s[11]||(s[11]=e(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[12]||(s[12]=[e("LCTT",-1)])]),_:1}),s[15]||(s[15]=e(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...s[13]||(s[13]=[e("Linux中國",-1)])]),_:1}),s[16]||(s[16]=e(" 榮譽推出",-1))])])}const v=l(h,[["render",g]]);export{y as __pageData,v as default};
